const inputs = [
  "/foo", "/foo?", "/foo?bar=1", "/foo?bar=1&baz=2", "/foo?a=1&a=2&bar=3#frag",
  "https://user:pw@example.com:8080/p/a?bar=1&q=%20x+y#h", "?bar=1&c=3", "//cdn.example.com/x?bar=1&y",
