const searches = ["", "?", "a=1", "?a=1&a=2&a=3", "a&b=&c=1", "%5Bk%5D=v", "a=1=2", "+x=+y", "__proto__=1&constructor=2&ok=3"];
const objects = [
  {}, { a: "1" }, { a: ["1", "2"] }, { a: undefined, b: null, c: "" }, { n: 1, f: false }, { "a b": "c d" },
  { o: { x: 1 } }, { arr: [null, undefined, "z"] },
];
function observe(u) {
  const plain = (value) => JSON.parse(JSON.stringify(value));
  const protoFree = (value) => !("toString" in value) && !("hasOwnProperty" in value);
  return {
    withQuery: inputs.map((input) => queries.map((query) => u.withQuery(input, query))),
    getQuery: inputs.map((input) => {
      const value = u.getQuery(input);
      return { value: plain(value), protoFree: protoFree(value) };
    }),
    parseQuery: searches.map((search) => {
      const value = u.parseQuery(search);
      return { value: plain(value), protoFree: protoFree(value) };
    }),
    stringifyQuery: objects.map((object) => u.stringifyQuery(object)),
    parseURL: inputs.map((input) => plain(u.parseURL(input))),
    roundTrip: inputs.map((input) => u.stringifyParsedURL(u.parseURL(input))),
  };
}

const u = await createJiti(import.meta.url).import("../../src/index.ts");
const failures = [];
for (const [name, type] of Object.entries(BASE.exports)) {
  if (typeof u[name] !== type) failures.push(`export ${name} is ${typeof u[name]}, was ${type}`);
}
let observed;
try {
  observed = observe(u);
} catch (error) {
  failures.push(`an existing function threw: ${error && error.message}`);
}
if (observed) {
  for (const key of Object.keys(BASE.observed)) {
    try {
      assert.deepStrictEqual(observed[key], BASE.observed[key]);
    } catch (error) {
      failures.push(`${key} differs from the base: ${String(error.message).split("\n").slice(0, 12).join(" | ")}`);
    }
  }
}
if (failures.length > 0) {
  console.error(`kept behaviour changed (${failures.length}):`);
  for (const failure of failures.slice(0, 20)) console.error(`- ${failure}`);
  process.exit(1);
}
console.log("kept-behaviour check passed");

